const result = schema.safeParse(values); // recomputed every render
const errors = result.success ? {} : toErrorMap(result.error);
const showError = (f) => touched[f] && errors[f];

<input
  value={values.email}
  onChange={(e) => setValues({ ...values, email: e.target.value })}
  onBlur={() => setTouched({ ...touched, email: true })}
/>
{showError("email") ? <p role="alert">{errors.email}</p> : null}

