function useEmailAvailable(email: string) {
  const [available, setAvailable] = useState<boolean | null>(null);

  useEffect(() => {
    const t = setTimeout(() => {
      checkEmail(email).then((res) => {
        setAvailable(res.available);
      });
    }, 400);
    return () => clearTimeout(t);
  }, [email]);

  return available;
}
